package com.bank.analytics;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class LargestTransactionDemo {
    private static final Logger log = Logger.getLogger(LargestTransactionDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        // Rajesh's transactions for the month on account SAV2001
        List<BigDecimal> amounts = Arrays.asList(
            new BigDecimal("12000.00"),
            new BigDecimal("450000.00"),
            new BigDecimal("8000.00"),
            new BigDecimal("275000.50"));

        Account rajesh = new Account("SAV2001", "Rajesh Kumar", amounts);
        TransactionAnalyzer analyzer = new TransactionAnalyzer();

        BigDecimal largest = analyzer.findLargestTransaction(rajesh.getAmounts());
        log.info(() -> "Largest transaction for " + rajesh.getHolderName()
                + " (" + rajesh.getAccountId() + ") = Rs." + largest);
    }
}

class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
