package com.bank.analytics;

import java.math.BigDecimal;
import java.util.List;

class TransactionAnalyzer {

    // O(n) scan: seed with first element, upgrade when a bigger one appears.
    BigDecimal findLargestTransaction(List<BigDecimal> amounts) {
        if (amounts == null || amounts.isEmpty()) {
            throw new IllegalArgumentException("No transactions: largest is undefined");
        }
        BigDecimal max = amounts.get(0);            // assume first is biggest
        for (int i = 1; i < amounts.size(); i++) {
            BigDecimal current = amounts.get(i);
            if (current.compareTo(max) > 0) {       // found something bigger
                max = current;                      // upgrade the record holder
            }
        }
        return max;
    }
}
